def _e_tcc(pasta: Path) -> bool:
    return (pasta / 'pesquisar_cash_calibracao_spyder.py').is_file() and (
        pasta / 'reproduzir_experimento.py').is_file()


def encontrar_raiz() -> Path:
    # A localizacao do instalador e o diretorio de trabalho do Spyder podem diferir.
    candidatos = [Path.cwd(), Path(__file__).resolve().parent]
    for ponto in candidatos:
        for pasta in (ponto, *ponto.parents):
            if _e_tcc(pasta):
                return pasta
    raise FileNotFoundError(
        'Projeto TCC nao encontrado. Abra a pasta tcc_mba_usp_data_science_analytics '
        'no Spyder e execute este arquivo novamente. Nenhum caminho precisa ser informado.'
    )


def conferir_arquivo(path: Path) -> bool:
    if not path.is_file():
        return False
    if hashlib.sha256(path.read_bytes()).hexdigest() == SHA256_OFICIAL:
        return True
    try:
        with zipfile.ZipFile(path) as z:
            info = json.loads(z.read('reproducao_universo.json'))
            # Mesmo resultado, versao, e arquivos necessarios: preserve pacote local.
            nomes = set(z.namelist())
            return (info.get('reproduction_version') == '1.23.0'
                    and info.get('reproduced_exact_to_cent') is True
                    and abs(float(info['metrics']['ending_capital']) - CAPITAL_FINAL_OFICIAL) < 0.01
                    and {'predictions.csv', 'fold_calibration.csv', 'reproducao_universo.json'} <= nomes)
    except (OSError, KeyError, ValueError, zipfile.BadZipFile):
        return False


def instalar_pacote(raiz: Path) -> Path:
    destino = raiz / ARQUIVO_RELATIVO
    destino.parent.mkdir(parents=True, exist_ok=True)
    if conferir_arquivo(destino):
        print('[OK] Reproducao oficial ja presente:', destino)
        return destino
    dados = base64.b64decode(''.join(ARQUIVO_BASE64.split()))
    obtido = hashlib.sha256(dados).hexdigest()
    if obtido != SHA256_OFICIAL:
        raise RuntimeError(f'Arquivo incorporado corrompido: {obtido} != {SHA256_OFICIAL}')
    with zipfile.ZipFile(__import__('io').BytesIO(dados)) as z:
        esperados = {'predictions.csv', 'fold_calibration.csv', 'reproducao_universo.json'}
        if not esperados.issubset(z.namelist()):
            raise RuntimeError('Pacote incorporado incompleto.')
    # O arquivo anterior, caso exista e nao passe na conferencia, fica guardado.
    if destino.exists():
        backup = destino.with_suffix('.zip.backup')
        if backup.exists():
            raise RuntimeError(f'Backup anterior ja existe: {backup}. Nada foi sobrescrito.')
        destino.replace(backup)
        print('[INFO] Versao anterior preservada:', backup)
    with tempfile.NamedTemporaryFile(mode='wb', dir=destino.parent, delete=False,
                                     prefix='pacote_cash_', suffix='.part') as temp:
        temp.write(dados)
        temporario = Path(temp.name)
    try:
        os.replace(temporario, destino)
    finally:
        temporario.unlink(missing_ok=True)
    print('[OK] Pacote completo criado automaticamente:', destino)
    print('[OK] SHA-256:', SHA256_OFICIAL)
    return destino


def executar() -> dict:
    raiz = encontrar_raiz()
    print('[INFO] Raiz identificada automaticamente:', raiz)
    pacote = instalar_pacote(raiz)
    arquivo_pesquisa = raiz / 'pesquisar_cash_calibracao_spyder.py'
    spec = importlib.util.spec_from_file_location('pesquisa_cash_auto', arquivo_pesquisa)
    if spec is None or spec.loader is None:
        raise RuntimeError('Nao foi possivel carregar a pesquisa CASH do projeto.')
    modulo = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(modulo)
    destino = raiz / 'output' / 'pesquisa_cash_calibracao'
    resultado = modulo.analisar(pacote, destino)
    print('[OK] Pesquisa concluida. Resultados gerados em:', destino)
    print(json.dumps(resultado, ensure_ascii=False, indent=2))
    return resultado


if __name__ == '__main__':
    executar()